"""Validators over depot harness outputs (later batch: V7-V9).

Each validator vN(items) returns (passed, measured). An empty input never passes.
"""

# Assumed inclusive bounds for supplier reliability (V9). The spec did not state them.
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def _is_int(value):
    """True for real ints; bool is excluded even though it subclasses int."""
    return isinstance(value, int) and not isinstance(value, bool)


def _within_capacity(entry):
    """True when max_units is an int no greater than capacity (also an int)."""
    capacity = entry["capacity"]
    max_units = entry["max_units"]
    return _is_int(capacity) and _is_int(max_units) and max_units <= capacity


def v7(items):
    """Every warehouse's max_units stayed within its capacity across runs.

    measured: list of wh names that exceeded capacity (or malformed).
    """
    if not items:
        return False, []
    bad = []
    for entry in items:
        try:
            ok = _within_capacity(entry)
            wh = entry.get("wh")
        except (KeyError, TypeError, AttributeError):
            ok = False
            wh = None
        if not ok:
            bad.append(wh)
    return not bad, bad


def _notice_key(item):
    """Turn a [sku, wh, qty] triple into a hashable tuple; reject anything else."""
    if not isinstance(item, (list, tuple)) or len(item) != 3:
        raise ValueError("expected a [sku, wh, qty] triple")
    return tuple(item)


def _all_expiries_notified(entry):
    """True when every expired triple also appears among the notified triples.

    An entry with no expiries has nothing to notify and passes.
    """
    wanted = {_notice_key(x) for x in entry["expired"]}
    sent = {_notice_key(x) for x in entry["notified"]}
    return wanted <= sent


def v8(items):
    """All expiries were notified: every expired [sku, wh, qty] has a matching notification.

    measured: list of indices of entries with un-notified expiries (or malformed).
    """
    if not items:
        return False, []
    bad = []
    for i, entry in enumerate(items):
        try:
            ok = _all_expiries_notified(entry)
        except (KeyError, TypeError, AttributeError, ValueError):
            ok = False
        if not ok:
            bad.append(i)
    return not bad, bad


def _reliability_in_range(value):
    """True when value is an int within [RELIABILITY_MIN, RELIABILITY_MAX]."""
    return _is_int(value) and RELIABILITY_MIN <= value <= RELIABILITY_MAX


def v9(items):
    """Every supplier's reliability stayed within the allowed range.

    measured: list of supplier names out of range (or malformed).
    """
    if not items:
        return False, []
    bad = []
    for entry in items:
        try:
            ok = _reliability_in_range(entry["reliability"])
            supplier = entry.get("supplier")
        except (KeyError, TypeError, AttributeError):
            ok = False
            supplier = None
        if not ok:
            bad.append(supplier)
    return not bad, bad
