import unittest

from validators_later import v7, v8, v9


class TestV7(unittest.TestCase):
    def test_empty_never_passes(self):
        self.assertEqual(v7([]), (False, []))

    def test_within_capacity_passes(self):
        items = [{"wh": "A", "capacity": 10, "max_units": 10},
                 {"wh": "B", "capacity": 10, "max_units": 3}]
        self.assertEqual(v7(items), (True, []))

    def test_over_capacity_reports_wh(self):
        items = [{"wh": "A", "capacity": 10, "max_units": 11},
                 {"wh": "B", "capacity": 10, "max_units": 1}]
        self.assertEqual(v7(items), (False, ["A"]))

    def test_malformed_fails(self):
        items = [{"wh": "A", "capacity": 10},
                 {"wh": "B", "capacity": True, "max_units": 1},
                 "junk"]
        self.assertEqual(v7(items), (False, ["A", "B", None]))


class TestV8(unittest.TestCase):
    def test_empty_never_passes(self):
        self.assertEqual(v8([]), (False, []))

    def test_all_notified_passes(self):
        items = [{"expired": [["s1", "A", 2]],
                  "notified": [["s1", "A", 2], ["s2", "B", 1]]}]
        self.assertEqual(v8(items), (True, []))

    def test_no_expiries_passes(self):
        self.assertEqual(v8([{"expired": [], "notified": []}]), (True, []))

    def test_missing_notification_reports_index(self):
        items = [{"expired": [["s1", "A", 2]], "notified": [["s1", "A", 1]]},
                 {"expired": [["s2", "B", 1]], "notified": [["s2", "B", 1]]}]
        self.assertEqual(v8(items), (False, [0]))

    def test_malformed_fails(self):
        items = [{"expired": [["s1", "A"]], "notified": []},
                 {"expired": "x", "notified": []},
                 {"expired": [], "notified": [[["unhashable"], "A", 1]]}]
        self.assertEqual(v8(items), (False, [0, 1, 2]))


class TestV9(unittest.TestCase):
    def test_empty_never_passes(self):
        self.assertEqual(v9([]), (False, []))

    def test_in_range_passes(self):
        items = [{"supplier": "X", "reliability": 0},
                 {"supplier": "Y", "reliability": 100}]
        self.assertEqual(v9(items), (True, []))

    def test_out_of_range_reports_supplier(self):
        items = [{"supplier": "X", "reliability": -1},
                 {"supplier": "Y", "reliability": 101},
                 {"supplier": "Z", "reliability": 50}]
        self.assertEqual(v9(items), (False, ["X", "Y"]))

    def test_malformed_fails(self):
        items = [{"supplier": "X", "reliability": 50.0},
                 {"supplier": "Y", "reliability": True},
                 {"reliability": 10},
                 42]
        self.assertEqual(v9(items), (False, ["X", "Y", None, None]))


if __name__ == "__main__":
    unittest.main()
